dependencies, errors = {}, {}
for name in ('pytest', 'numpy', 'PIL'):
    try:
        module = importlib.import_module(name)
        dependencies[name] = {'version': getattr(module, '__version__', None),
                              'path': getattr(module, '__file__', None)}
